codeExamples.tech2Snippet:
// Hono: Minimaler Server (z. B. für Deno)
import { Hono } from 'https://deno.land/x/hono/mod.ts';

const app = new Hono();
app.get('/', (c) => c.text('Hello, World!'));

Deno.serve(app.fetch);
